-- -----------------------------------
-- Table structure for `daily_sbi_downsite_table`
-- -----------------------------------

DROP TABLE IF EXISTS `daily_sbi_downsite_table`;
CREATE TABLE `daily_sbi_downsite_table` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ATMID` varchar(100) NOT NULL,
  `last_communication` date NOT NULL,
  `SN` int(11) NOT NULL,
  `today_date` date NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=245 DEFAULT CHARSET=utf8mb4;

